<?php
declare(strict_types=1);
require_once __DIR__.'/../libs/config-loader.inc.php';
require_once dirname(__DIR__).'/libs/kernel.inc.php';
$uid=alphanoRequireLogin();if(!alphanoCan('admin')){alphanoFail('Accesso riservato agli amministratori completi.',403);}
$sections=['defaults'=>'Colori e disposizione','home'=>'Homepage e manuali','groups'=>'Immagini dei menu','items'=>'Immagini dei sottomenu','pages'=>'Sfondi di tutte le pagine'];
$section=$_GET['section']??'defaults';if(!is_string($section)||!isset($sections[$section])){$section='defaults';}
$target=$_GET['target']??'';if(!is_string($target)){$target='';}
$groups=alphanoLoadConfig(dirname(__DIR__).'/config/navigation.php');$catalog=alphanoAppearanceCatalog();$menu=alphanoAppearanceMenuCatalog();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(empty($_POST)&&(int)($_SERVER['CONTENT_LENGTH']??0)>0){alphanoFail('Caricamento troppo grande per il server. Carica un’immagine alla volta (limite complessivo: '.ini_get('post_max_size').').',413);}
    alphanoRequireCsrf();
    try{
        $posted=$_POST['section']??'';if($posted!==$section||($_POST['target']??'')!==$target){throw new DomainException('Destinazione non valida.');}
        $layout=[];
        if($section==='defaults'){foreach(['theme'=>array_keys(alphanoThemes()),'sidebar_position'=>['left','right'],'header_position'=>['top','bottom']] as $key=>$allowed){if(!in_array($_POST[$key]??'', $allowed,true)){throw new DomainException('Opzione non valida: '.$key);}$layout[$key]=$_POST[$key];}}
        alphanoAppearanceSave($_POST,$_FILES,$groups);
        if($layout){$file=dirname(__DIR__).'/private/settings.json';$old=is_file($file)?json_decode(file_get_contents($file),true,32,JSON_THROW_ON_ERROR):[];alphanoSettingsWrite(array_replace($old,$layout));}
        connectDB()->execute('INSERT INTO engine_admin_audit(actor,action,created_at) VALUES(?,?,?)',[$uid,'appearance:'.$section.':'.$target,time()]);
        header('Location: /admin/appearance.php?'.http_build_query(['section'=>$section,'target'=>$target,'saved'=>1]),true,303);exit;
    }catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():'Salvataggio non riuscito. Controlla il log del server.';if(!$e instanceof DomainException){error_log('[Appearance] '.$e->getMessage());}http_response_code(422);}
}
$a=alphanoAppearance();$config=alphanoLoadConfig(dirname(__DIR__).'/config/app.php');$selection=null;
if($section==='groups'&&isset($groups[$target])){$selection=['label'=>$groups[$target]['title']];}
if($section==='items'&&isset($menu[$target])){$selection=$menu[$target];}
if($section==='pages'&&isset($catalog[$target])){$selection=$catalog[$target];}
$values=in_array($section,['defaults','home'],true)?($a[$section]??[]):($a[$section][$target]??[]);
if($section==='groups'&&$selection){$values['default_image']=$groups[$target]['image'];}
if($section==='items'&&$selection){$defaults=alphanoLoadConfig(dirname(__DIR__).'/config/navigation-icons.php');$values['default_image']=$defaults[$selection['label']]??$groups[$selection['group']]['image'];}
if($section==='home'){$values+=['default_logo'=>'/assets/alphanogdr-logo.png','default_banner'=>alphanoAppearancePage('/')['header'],'default_scene_library'=>alphanoDefaultArt('header-library')];}
if($section==='pages'&&$selection){$values['default_header']=alphanoAppearancePage($selection['url'])['header'];}
if($section==='defaults'){$values['default_header']=alphanoDefaultArt('header-panorama');}
function appearanceImageField(string $name,string $label,array $values): void {
    $value=$values[$name]??'';$id='preview-'.$name;$fallback=$values['default_'.$name]??'/assets/placeholder.svg';
    echo '<div class="appearance-image-field"><label>'.alphanoEscape($label).'<input type="file" name="'.$name.'" accept="image/png,image/jpeg,image/webp" data-image-preview="'.$id.'"></label><label>Immagine del pacchetto<select aria-label="Immagine del pacchetto: '.alphanoEscape($label).'" name="preset_'.$name.'" data-default-art-picker="'.$id.'"><option value="">Usa percorso o caricamento · eredita il predefinito</option>';
    foreach(alphanoDefaultArtCatalog() as $asset){echo '<option value="'.alphanoEscape($asset['path']).'">'.alphanoEscape($asset['title']).'</option>';}
    echo '</select></label><img id="'.$id.'" class="appearance-preview" data-default-src="'.alphanoEscape($fallback).'" src="'.alphanoEscape($value?:$fallback).'" alt="Anteprima '.alphanoEscape($label).'" width="220" height="110"><label>Percorso già presente sul sito<input type="text" name="'.$name.'" value="'.alphanoEscape($value).'" placeholder="/uploads/appearance/immagine.png"></label><label class="check"><input type="checkbox" name="remove_'.$name.'" value="1">Rimuovi la personalizzazione</label></div>';
}
function appearanceSelect(string $key,string $label,array $options,array $config): void {
    echo '<label>'.$label.'<select name="'.$key.'">';foreach($options as $value=>$title){echo '<option value="'.$value.'"'.($config[$key]===$value?' selected':'').'>'.alphanoEscape($title).'</option>';}echo '</select></label>';
}
?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><title>Template e homepage</title></head><body class="engine-admin appearance-admin"<?=isset($_GET['saved'])?' data-appearance-saved':''?>><main class="admin-wrap">
<header data-page-heading><div><p class="eyebrow">Gestione · Aspetto del gioco</p><h1>Template e homepage</h1><p>Colori coerenti, immagini e disposizione per costruire l’identità del tuo mondo.</p></div></header>
<p><a href="/admin/settings.php">Impostazioni generali ed email</a> · <a href="/admin/setup.php?step=appearance">Configurazione guidata</a> · <a href="/main.php">Torna al gioco</a> · <a href="/?preview=1" target="_blank" rel="noopener">Apri il sito</a></p>
<nav class="appearance-tabs" aria-label="Personalizzazione"><?php foreach($sections as $key=>$title):?><a href="?section=<?=$key?>"<?=$section===$key?' aria-current="page"':''?>><?=alphanoEscape($title)?></a><?php endforeach;?></nav>
<?php if($error):?><p class="error" role="alert"><?=alphanoEscape($error)?></p><?php elseif(isset($_GET['saved'])):?><p class="notice" aria-live="polite">Personalizzazione salvata. Il tema si aggiorna anche nelle pagine del gioco già aperte. Le bozze della chat rimangono nel campo di scrittura.</p><?php endif;?>
<?php if(in_array($section,['defaults','home'],true)||$selection):?>
<form method="post" enctype="multipart/form-data" class="appearance-editor"><input type="hidden" name="_csrf" value="<?=alphanoCsrfToken()?>"><input type="hidden" name="revision" value="<?=alphanoAppearanceRevision()?>"><input type="hidden" name="section" value="<?=$section?>"><input type="hidden" name="target" value="<?=alphanoEscape($target)?>">
<h2><?=alphanoEscape($selection['label']??$sections[$section])?></h2>
<?php if($selection&&isset($selection['url'])):?><p class="muted"><?=alphanoEscape($selection['url'])?> · Le immagini cambiano soltanto l’aspetto: i permessi della pagina restano quelli del gioco.</p><?php endif;?>
<?php if($section==='defaults'):?><fieldset><legend>Palette e disposizione</legend><?php appearanceSelect('theme','Colori',alphanoThemes(),$config);appearanceSelect('sidebar_position','Colonna del personaggio',['left'=>'A sinistra','right'=>'A destra'],$config);appearanceSelect('header_position','Menu principale',['top'=>'Sopra il contenuto','bottom'=>'Sotto il contenuto'],$config);?><p>I sottomenu si aprono verso l’alto quando la navigazione è in basso. Tutte le pagine e gli iframe usano la palette selezionata.</p></fieldset><fieldset><legend>Immagini comuni a tutte le pagine</legend><?php appearanceImageField('background','Sfondo generale',$values);appearanceImageField('header','Sfondo delle intestazioni',$values);?></fieldset>
<?php elseif($section==='home'):?><fieldset><legend>Identità della homepage</legend><label>Titolo di presentazione<input name="headline" maxlength="160" value="<?=alphanoEscape($values['headline']??'')?>" placeholder="Usa il nome del gioco"></label><label>Testo di presentazione<textarea name="intro" maxlength="2000" rows="5" placeholder="Usa la descrizione generale"><?=alphanoEscape($values['intro']??'')?></textarea></label><?php appearanceImageField('background','Sfondo della homepage',$values);appearanceImageField('banner','Banner panoramico',$values);appearanceImageField('logo','Logo del gioco',$values);?></fieldset><fieldset><legend>Illustrazioni della homepage</legend><p>Le immagini originali sono già incluse. Puoi sostituirle tutte e tornare ai valori del pacchetto con «Rimuovi la personalizzazione».</p><?php appearanceImageField('scene_library','La biblioteca dei manuali',$values);?></fieldset><fieldset><legend>Manuali fissati in homepage</legend><p>Le guide selezionate compaiono prima dell’accesso. Sono selezionabili solo capitoli pubblici: se un capitolo diventa riservato, scompare automaticamente dalla homepage.</p><?php $manuals=alphanoAppearancePublicManuals();if(!$manuals):?><p>Crea prima i capitoli nella <a href="/regole/">gestione dei manuali</a>.</p><?php endif;foreach($manuals as $manual):?><label class="check"><input type="checkbox" name="manuals[]" value="<?=(int)$manual['id']?>"<?=in_array((int)$manual['id'],$values['manuals']??[],true)?' checked':''?>><?=alphanoEscape($manual['oggetto'])?></label><?php endforeach;?></fieldset>
<?php elseif(in_array($section,['groups','items'],true)):?><p>Senza una personalizzazione viene usata l’immagine originale del pacchetto. Puoi sceglierne un’altra dalla libreria predefinita oppure caricare la tua.</p><?php appearanceImageField('image','Immagine della voce',$values);?>
<?php else:?><p>Ogni pagina ha già un’intestazione illustrata adatta alla sua sezione. I campi vuoti ereditano le personalizzazioni comuni oppure l’immagine predefinita. Per città, razze e chat puoi assegnare uno sfondo specifico oltre a quello comune della sezione.</p><fieldset><legend>Immagini di questa pagina</legend><?php appearanceImageField('background','Sfondo della pagina',$values);appearanceImageField('header','Sfondo dell’intestazione',$values);?></fieldset><?php endif;?>
<p class="muted">Formati PNG, JPEG e WebP, massimo 5 MB per file. Per icone: immagine quadrata di almeno 128 × 128 pixel. Per banner e sfondi: immagine panoramica.</p><button type="submit">Salva personalizzazione</button></form>
<?php endif;?>
<?php if(!in_array($section,['defaults','home'],true)):?>
<section class="appearance-catalog"><h2><?=$section==='pages'?'Catalogo completo delle pagine':($section==='groups'?'Menu principali':'Tutte le voci dei sottomenu')?></h2><label>Cerca nel catalogo<input type="search" data-appearance-filter placeholder="Nome, gruppo o percorso della pagina"></label><p class="muted">Le voci disponibili in gioco dipendono dai moduli e dai permessi attivi. Il catalogo comprende anche le pagine riservate e quelle dei moduli facoltativi.</p><div class="appearance-rows">
<?php $entries=$section==='groups'?array_map(static fn($key,$g)=>['key'=>$key,'label'=>$g['title'],'group'=>$key,'url'=>''],array_keys($groups),array_values($groups)):($section==='items'?array_values($menu):array_values($catalog));foreach($entries as $entry):$key=$entry['key'];$current=$a[$section][$key]??[];$image=$current['image']??$current['header']??$current['background']??'';if($image===''&&$section==='pages'){$image=alphanoAppearancePage($entry['url'])['header'];}if($image===''&&$section==='groups'){$image=$groups[$key]['image']??'';}if($image===''&&$section==='items'){$image=$entry['image']??alphanoDefaultArt($entry['icon']??'scroll');}?><article data-appearance-row><div class="appearance-row-image"><?php if($image):?><img src="<?=alphanoEscape($image)?>" alt="" width="64" height="64" loading="lazy"><?php else:?><span data-icon="<?=alphanoEscape($groups[$entry['group']]['icon']??'scroll')?>" aria-hidden="true"></span><?php endif;?></div><div><small><?=alphanoEscape($groups[$entry['group']]['title']??ucfirst($entry['group']))?></small><h3><?=alphanoEscape($entry['label'])?></h3><code><?=alphanoEscape($entry['url'])?></code></div><a class="button secondary" href="?<?=alphanoEscape(http_build_query(['section'=>$section,'target'=>$key]))?>">Personalizza<span class="sr-only"> <?=alphanoEscape($entry['label'])?></span></a></article><?php endforeach;?>
</div></section><?php endif;?></main></body></html>
